import{_ as a,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"17 | 为什么不建议你使用自增主键？","description":"","frontmatter":{},"headers":[{"level":2,"title":"自增主键的特性","slug":"自增主键的特性","link":"#自增主键的特性","children":[]},{"level":2,"title":"单体数据库的自增主键","slug":"单体数据库的自增主键","link":"#单体数据库的自增主键","children":[{"level":3,"title":"无法连续递增","slug":"无法连续递增","link":"#无法连续递增","children":[]},{"level":3,"title":"无法单调递增","slug":"无法单调递增","link":"#无法单调递增","children":[]}]},{"level":2,"title":"自增主键的问题","slug":"自增主键的问题","link":"#自增主键的问题","children":[{"level":3,"title":"尾部热点","slug":"尾部热点","link":"#尾部热点","children":[]}]},{"level":2,"title":"随机主键方案","slug":"随机主键方案","link":"#随机主键方案","children":[{"level":3,"title":"内置UUID","slug":"内置uuid","link":"#内置uuid","children":[]},{"level":3,"title":"内置Radom ID","slug":"内置radom-id","link":"#内置radom-id","children":[]},{"level":3,"title":"外置Snowflake","slug":"外置snowflake","link":"#外置snowflake","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"学习资料","slug":"学习资料","link":"#学习资料","children":[]}],"relativePath":"分布式数据库30讲/17-为什么不建议你使用自增主键？.md","filePath":"分布式数据库30讲/17-为什么不建议你使用自增主键？.md","lastUpdated":1779818976000}'),s={name:"分布式数据库30讲/17-为什么不建议你使用自增主键？.md"};function l(r,e,o,c,p,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="_17-为什么不建议你使用自增主键" tabindex="-1">17 | 为什么不建议你使用自增主键？ <a class="header-anchor" href="#_17-为什么不建议你使用自增主键" aria-label="Permalink to &quot;17 | 为什么不建议你使用自增主键？&quot;">​</a></h1><p>你好，我是王磊，你也可以叫我Ivan。</p><p>有经验的数据库开发人员一定知道，数据库除了事务处理、查询引擎这些核心功能外，还会提供一些小特性。它们看上去不起眼，却对简化开发工作很有帮助。</p><p>不过，这些特性的设计往往是以单体数据库架构和适度的并发压力为前提的。随着业务规模扩大，在真正的海量并发下，这些特性就可能被削弱或者失效。在分布式架构下，是否要延续这些特性也存在不确定性，我们今天要聊的自增主键就是这样的小特性。</p><p>虽然，我对自增主键的态度和 <a href="https://time.geekbang.org/column/article/285270" target="_blank" rel="noreferrer">第16讲</a> 提到的存储过程一样，都不推荐你使用，但是原因各有不同。存储过程主要是工程方面的原因，而自增主键则是架构上的因素。好了，让我们进入正题吧。</p><h2 id="自增主键的特性" tabindex="-1">自增主键的特性 <a class="header-anchor" href="#自增主键的特性" aria-label="Permalink to &quot;自增主键的特性&quot;">​</a></h2><p>自增主键在不同的数据库中的存在形式稍有差异。在MySQL中，你可以在建表时直接通过关键字auto_increment来定义自增主键，例如这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create table ‘test’ (</span></span>
<span class="line"><span>  ‘id’  int(16) NOT NULL AUTO_INCREMENT,</span></span>
<span class="line"><span>  ‘name’  char(10) DEFAULT NULL,</span></span>
<span class="line"><span>  PRIMARY KEY(‘id’)</span></span>
<span class="line"><span>) ENGINE = InnoDB;</span></span></code></pre></div><p>而在Oracle中则是先声明一个连续的序列，也就是sequence，而后在insert语句中可以直接引用sequence，例如下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create sequence test_seq increment by 1 start with 1;</span></span>
<span class="line"><span>insert into test(id, name) values(test_seq.nextval, &#39; An example &#39;);</span></span></code></pre></div><p>自增主键给开发人员提供了很大的便利。因为，主键必须要保证唯一，而且多数设计规范都会要求，主键不要带有业务属性，所以如果数据库没有内置这个特性，应用开发人员就必须自己设计一套主键的生成逻辑。数据库原生提供的自增主键免去了这些工作量，而且似乎还能满足开发人员的更多的期待。</p><p>这些期待是什么呢？我总结了一下，大概有这么三层：</p><ul><li>首先是唯一性，这是必须保证的，否则还能叫主键吗？</li><li>其次是单调递增，也就是后插入记录的自增主键值一定比先插入记录要大。</li><li>最后就是连续递增，自增主键每次加1。有些应用系统甚至会基于自增主键的“连续递增”特性来设计业务逻辑。</li></ul><h2 id="单体数据库的自增主键" tabindex="-1">单体数据库的自增主键 <a class="header-anchor" href="#单体数据库的自增主键" aria-label="Permalink to &quot;单体数据库的自增主键&quot;">​</a></h2><p>但是，我接下来的分析可能会让你失望，因为除了最基本的唯一性，另外的两层期待都是无法充分满足的。</p><h3 id="无法连续递增" tabindex="-1">无法连续递增 <a class="header-anchor" href="#无法连续递增" aria-label="Permalink to &quot;无法连续递增&quot;">​</a></h3><p>首先说连续递增。在多数情况下，自增主键确实表现为连续递增。但是当事务发生冲突时，主键就会跳跃，留下空洞。下面，我用一个例子简单介绍下MySQL的处理过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/1ae285029b67aa128fd34c5cc3caf721.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/1ae285029b67aa128fd34c5cc3caf721.jpg" alt=""></a></p><p>两个事务T1和T2都要在同一张表中插入记录，T1先执行，得到的主键是25，而T2后执行，得到是26。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/7e48552810fcc500aec4f4c253a18e54.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/7e48552810fcc500aec4f4c253a18e54.jpg" alt=""></a></p><p>但是，T1事务还要操作其他数据库表，结果不走运，出现了异常，T1必须回滚。T2事务则正常执行成功，完成了事务提交。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/f8890f3f251cc74808f6fyy53a29526e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/f8890f3f251cc74808f6fyy53a29526e.jpg" alt=""></a></p><p>这样，在数据表中就缺少主键为25的记录，而当下一个事务T3再次申请主键时，得到的就是27，那么25就成了永远的空洞。</p><p>为什么不支持连续递增呢？这是因为自增字段所依赖的计数器并不是和事务绑定的。如果要做到连续递增，就要保证计数器提供的每个主键都被使用。</p><p>怎么确保每个主键都被使用呢？那就要等待使用主键的事务都提交成功。这意味着，必须前一个事务提交后，计数器才能为后一个事务提供新的主键，这个计数器就变成了一个表级锁。</p><p>显然，如果存在这么大粒度的锁，性能肯定会很差，所以MySQL优先选择了性能，放弃了连续递增。至于那些因为事务冲突被跳过的数字呢，系统也不会再回收重用了，这是因为要保证自增主键的单调递增。</p><p>看到这里你可能会想， 虽然实现不了连续递增，但至少能保证单调递增，也不错。那么，我要再给你泼一盆冷水了，这个单调递增有时也是不能保证的。</p><h3 id="无法单调递增" tabindex="-1">无法单调递增 <a class="header-anchor" href="#无法单调递增" aria-label="Permalink to &quot;无法单调递增&quot;">​</a></h3><p>对于单体数据库自身来说，自增主键确实是单调递增的。但使用自增主键也是有前提的，那就是主键生成的速度要能够满足应用系统的并发需求。而在高并发量场景下，每个事务都要去申请主键，数据库如果无法及时处理，自增主键就会成为瓶颈。那么，这时只用自增主键已经不能解决问题了，往往还要在应用系统上做些优化。</p><p>比如，对于Oracle数据库，常见的优化方式就是由Sequence负责生成主键的高位，由应用服务器负责生成低位数字，拼接起来形成完整的主键。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/f2b6cc531b0dbec7d19f191b6225b20c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/f2b6cc531b0dbec7d19f191b6225b20c.jpg" alt=""></a></p><p>图中展示这样的例子，数据库的Sequence 是一个5位的整型数字，范围从10001到99999。每个应用系统实例先拿到一个号，比如10001，应用系统在使用这5位为作为高位，自己再去拼接5位的低位，这样得到一个10位长度的主键。这样，每个节点访问一次Sequence就可以处理99999次请求，处理过程是基于应用系统内存中的数据计算主键，没有磁盘I/O开销，而相对的Sequence递增时是要记录日志的，所以方案改进后性能有大幅度提升。</p><p>这个方案虽然使用了Sequence，但也只能保证全局唯一，数据表中最终保存的主键不再是单调递增的了。</p><p>因为，几乎所有数据库中的自增字段或者自增序列都是要记录日志的，也就都会产生磁盘I/O，也就都会面临这个性能瓶颈的问题。所以，我们可以得出一个结论：在一个海量并发场景下，即使借助单体数据库的自增主键特性，也不能实现单调递增的主键。</p><h2 id="自增主键的问题" tabindex="-1">自增主键的问题 <a class="header-anchor" href="#自增主键的问题" aria-label="Permalink to &quot;自增主键的问题&quot;">​</a></h2><p>对于分布式数据库，自增主键带来的麻烦就更大了。具体来说是两个问题，一是在自增主键的产生环节，二是在自增主键的使用环节。</p><p>首先，产生自增主键难点就在单调递增。如果你已经学习过 <a href="https://time.geekbang.org/column/article/274908" target="_blank" rel="noreferrer">第5讲</a> 就会发现，单调递增这个要求和全局时钟中的TSO是很相似的。你现在已经知道，TSO实现起来比较复杂，也容易成为系统的瓶颈，如果再用作主键的发生器，显然不大合适。</p><p>其次，使用单调递增的主键，也会给分布式数据库的写入带来问题。这个问题是在Range分片下发生的，我们通常将这个问题称为 “尾部热点”。</p><h3 id="尾部热点" tabindex="-1">尾部热点 <a class="header-anchor" href="#尾部热点" aria-label="Permalink to &quot;尾部热点&quot;">​</a></h3><p>我们先通过一组性能测试数据来看看尾部热点问题的现象，这些数据和图表来自 <a href="https://www.cockroachlabs.com/blog/unpacking-competitive-benchmarks/" target="_blank" rel="noreferrer">CockroachDB官网</a>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/5324e7ee83485724b062d6e8e72bcdd2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/5324e7ee83485724b062d6e8e72bcdd2.png" alt=""></a></p><p>这本身是一个CockraochDB与YugabyteDB的对比测试。测试环境使用亚马逊跨机房的三节点集群，执行SQL insert操作时，YugabyteDB的TPS达到58,877，而CockroachDB的TPS是34,587。YugabyteDB集群三个节点上的CPU都得到了充分使用，而CockroachDB集群中负载主要集中在一个节点上，另外两个节点的CPU多数情况都处于空闲状态。</p><p>为什么CockroachDB的节点负载这么不均衡呢？这是由于CockroachDB默认设置为Range分片，而测试程序的生成主键是单调递增的，所以新写入的数据往往集中在一个 Range 范围内，而Range又是数据调度的最小单位，只能存在于单节点，那么这时集群就退化成单机的写入性能，不能充分利用分布式读写的扩展优势了。当所有写操作都集中在集群的一个节点时，就出现了我们常说的数据访问热点（Hotspot）。</p><p>图中也体现了CockroachDB改为Hash分片时的情况，因为数据被分散到多个Range，所以TPS一下提升到61,113，性能达到原来的1.77倍。</p><p>现在性能问题的根因已经找到了，就是同时使用自增主键和Range分片。在 <a href="https://time.geekbang.org/column/article/275696" target="_blank" rel="noreferrer">第6讲</a> 我们已经介绍过了Range分片很多优势，这使得Range分片成为一个不能轻易放弃的选择。于是，主流产品的默认方案是保持Range分片，放弃自增主键，转而用随机主键来代替。</p><h2 id="随机主键方案" tabindex="-1">随机主键方案 <a class="header-anchor" href="#随机主键方案" aria-label="Permalink to &quot;随机主键方案&quot;">​</a></h2><p>随机主键的产生方式可以分为数据库内置和应用外置两种方式。当然对于应用开发者来说，内置方式使用起来会更加简便。</p><h3 id="内置uuid" tabindex="-1">内置UUID <a class="header-anchor" href="#内置uuid" aria-label="Permalink to &quot;内置UUID&quot;">​</a></h3><p>UUID（Universally Unique Identifier）可能是最经常使用的一种唯一ID算法，CockroachDB也建议使用UUID作为主键，并且内置了同名的数据类型和函数。UUID是由32个的16进制数字组成，所以每个UUID的长度是128位（16^32 = 2^128）。UUID作为一种广泛使用标准，有多个实现版本，影响它的因素包括时间、网卡MAC地址、自定义Namesapce等等。</p><p>但是，UUID的缺点很明显，那就是键值长度过长，达到了128位，因此存储和计算的代价都会增加。</p><h3 id="内置radom-id" tabindex="-1">内置Radom ID <a class="header-anchor" href="#内置radom-id" aria-label="Permalink to &quot;内置Radom ID&quot;">​</a></h3><p>TiDB默认是支持自增主键的，对未声明主键的表，会提供了一个隐式主键_tidb_rowid，因为这个主键大体上是单调递增的，所以也会出现我们前面说的“尾部热点”问题。</p><p>TiDB也提供了UUID函数，而且在4.0版本中还提供了另一种解决方案AutoRandom。TiDB 模仿MySQL的 AutoIncrement，提供了AutoRandom关键字用于生成一个随机ID填充指定列。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/4yy3c805599ebb98ba418a4c63220986.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/4yy3c805599ebb98ba418a4c63220986.jpg" alt=""></a></p><p>这个随机ID是一个64位整型，分为三个部分。</p><ul><li>第一部分的符号位没有实际作用。</li><li>第二部分是事务开始时间，默认为5位，可以理解为事务时间戳的一种映射。</li><li>第三部分则是自增的序列号, 使用其余位。</li></ul><p>AutoRandom可以保证表内主键唯一，用户也不需要关注分片情况。</p><h3 id="外置snowflake" tabindex="-1">外置Snowflake <a class="header-anchor" href="#外置snowflake" aria-label="Permalink to &quot;外置Snowflake&quot;">​</a></h3><p>雪花算法（Snowflake）是Twitter公司分布式项目采用的ID生成算法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/5a0738f8520a5d21582e896yy3413de2.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/5a0738f8520a5d21582e896yy3413de2.jpg" alt=""></a></p><p>这个算法生成的ID是一个64位的长整型，由四个部分构成：</p><ul><li>第一部分是1位的符号位，并没有实际用处，主要为了兼容长整型的格式。</li><li>第二部分是41位的时间戳用来记录本地的毫秒时间。</li><li>第三部分是机器ID，这里说的机器就是生成ID的节点，用10位长度给机器做编码，那意味着最大规模可以达到1024个节点（2^10）。</li><li>最后是12位序列，序列的长度直接决定了一个节点1毫秒能够产生的ID数量，12位就是4096（2^12）。</li></ul><p>这样，根据数据结构推算，雪花算法支持的TPS可以达到419万左右（2^22*1000），我相信对于绝大多数系统来说是足够了。</p><p>但实现雪花算法时，有个小问题往往被忽略，那就是要注意时间回拨带来的影响。机器时钟如果出现回拨，产生的ID就有可能重复，这需要在算法中特殊处理一下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>那么，今天的课程就到这里了，让我们梳理一下这一讲的要点。</p><ol><li>单体数据库普遍提供了自增主键或序列等方式，自动产生主键。单体数据库的自增主键保证主键唯一、单调递增，但在发生事务冲突时，并不能做到连续递增。在海量并发场景下，通常不能直接使用数据库的自增主键，因为它的性能不能满足要求。解决方式是应用系统进行优化，有数据库控制高位，应用系统控制低位，提升性能。但使用这种方案，主键不再是单调递增的。</li><li>分布式数据库在产生自增主键和使用自增主键两方面都有问题。生成自增主键时，要做到绝对的单调递增，其复杂度等同于TSO全局时钟，而且存在性能上限。使用自增主键时，会导致写入数据集中在单个节点，出现“尾部热点”问题。</li><li>由于自增主键的问题，有的分布式数据库，如CockroachDB更推荐使用随机主键的方式。随机主键的产生机制可以分为数据库内置和应用系统外置两种思路。内置的技术方案，我们介绍了CockraochDB的UUID和TiDB的RadomID。外置技术方案，我们介绍了Snowflake。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/6f4b43cfb79e1f1696c0fcb741d9ed4f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%9330%E8%AE%B2/images/285819/6f4b43cfb79e1f1696c0fcb741d9ed4f.jpg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>课程的最后，我们来看看今天的思考题。我们说如果分布式数据库使用Range分片的情况下，单调递增的主键会造成写入压力集中在单个节点上，出现“尾部热点”问题。因此，很多产品都用随机主键替换自增主键，分散写入热点。我的问题就是，你觉得使用随机主键是不是一定能避免出现“热点”问题呢？</p><p>欢迎你在评论区留言和我一起讨论，我会在答疑篇和你继续讨论这个问题。如果你身边的朋友也对分布式架构下如何设计主键这个话题感兴趣，你也可以把今天这一讲分享给他，我们一起讨论。</p><h2 id="学习资料" tabindex="-1">学习资料 <a class="header-anchor" href="#学习资料" aria-label="Permalink to &quot;学习资料&quot;">​</a></h2><p>CockroachDB: <a href="https://www.cockroachlabs.com/blog/unpacking-competitive-benchmarks/" target="_blank" rel="noreferrer"><em>Yugabyte vs CockroachDB: Unpacking Competitive Benchmark Claims</em></a></p>`,73)])])}const b=a(s,[["render",l]]);export{g as __pageData,b as default};
